/** Canonical SITREP setup validation and state construction. No UI or Foundry effects. */

import { FRAME_CONN_SITREP_DEFAULT_STATE, FRAME_CONN_SITREP_TYPES } from "../state/sitrep-state-contract.js";
import { normalizeSitrepState } from "../state/sitrep-state-normalization.js";

const DEFAULT_ROUND_LIMIT_BY_TYPE = Object.freeze({ control: 6, holdout: 6, extraction: 10, escort: 8, gauntlet: 8, recon: 8 });

function stringValue(value, fallback = "") { const normalized = String(value ?? "").trim(); return normalized || fallback; }
function stringList(value) { if (!Array.isArray(value)) return []; return [...new Set(value.map(candidate => String(candidate ?? "").trim()).filter(Boolean))]; }

export class SitrepSetupValidationError extends Error {
  constructor(errors) { super(`Invalid SITREP setup: ${errors.join("; ")}`); this.name = "SitrepSetupValidationError"; this.errors = Object.freeze([...errors]); }
}

export function validateSitrepSetup(request = {}) {
  const type = stringValue(request.type, FRAME_CONN_SITREP_DEFAULT_STATE.type).toLowerCase();
  const errors = [];
  if (!FRAME_CONN_SITREP_TYPES.includes(type)) errors.push(`Unknown SITREP type: ${type}.`);
  const regionId = stringValue(request.regionId);
  const controlRegionIds = stringList(request.controlRegionIds);
  const reconRegionIds = stringList(request.reconRegionIds);
  const reconTrueRegionId = stringValue(request.reconTrueRegionId);
  const escortObjectiveCombatantId = stringValue(request.escortObjectiveCombatantId);
  const escortExtractionRegionId = stringValue(request.escortExtractionRegionId);
  const extractionObjectiveCombatantId = stringValue(request.extractionObjectiveCombatantId);
  const extractionZoneRegionId = stringValue(request.extractionZoneRegionId);
  if (type === "control" && controlRegionIds.length !== 4) errors.push("Control requires exactly four Scene Regions.");
  if (type === "recon") {
    if (reconRegionIds.length !== 4) errors.push("Recon requires exactly four Control Zone Regions.");
    if (!reconTrueRegionId) errors.push("Recon requires one True Control Zone.");
    else if (!reconRegionIds.includes(reconTrueRegionId)) errors.push("The Recon True Control Zone must be one of the four configured Recon Regions.");
  }
  if (type === "escort") { if (!escortObjectiveCombatantId) errors.push("Escort requires an Objective combatant."); if (!escortExtractionRegionId) errors.push("Escort requires an Extraction Zone Region."); }
  if (type === "extraction") { if (!extractionObjectiveCombatantId) errors.push("Extraction requires an Objective combatant."); if (!extractionZoneRegionId) errors.push("Extraction requires an Extraction Zone Region."); }
  if ((type === "gauntlet" || type === "holdout") && !regionId) errors.push(`${type} requires a control Region.`);
  const roundLimit = Number(request.roundLimit ?? DEFAULT_ROUND_LIMIT_BY_TYPE[type] ?? 8);
  if (!Number.isFinite(roundLimit) || roundLimit < 1) errors.push("Round limit must be at least 1.");
  return Object.freeze({ valid: errors.length === 0, errors: Object.freeze(errors), type });
}

export function buildConfiguredSitrepState(request = {}, combat = null, existingState = null, { resetProgress = false } = {}) {
  const validation = validateSitrepSetup(request);
  if (!validation.valid) throw new SitrepSetupValidationError(validation.errors);
  const type = validation.type;
  const currentRound = Math.max(Number(combat?.round ?? existingState?.startRound ?? 1), 1);
  const roundLimit = Math.max(Number(request.roundLimit ?? existingState?.roundLimit ?? DEFAULT_ROUND_LIMIT_BY_TYPE[type] ?? 8), 1);
  const startRound = resetProgress ? currentRound : Math.max(Number(request.startRound ?? existingState?.startRound ?? currentRound), 1);
  const base = normalizeSitrepState(existingState ?? FRAME_CONN_SITREP_DEFAULT_STATE) ?? { ...FRAME_CONN_SITREP_DEFAULT_STATE };
  const configured = {
    ...base, type,
    title: stringValue(request.title, base.title), objective: stringValue(request.objective, base.objective),
    regionId: stringValue(request.regionId, type === "gauntlet" || type === "holdout" ? base.regionId : ""),
    controlRegionIds: type === "control" ? stringList(request.controlRegionIds) : [],
    escortObjectiveCombatantId: type === "escort" ? stringValue(request.escortObjectiveCombatantId) : "",
    escortExtractionRegionId: type === "escort" ? stringValue(request.escortExtractionRegionId) : "",
    extractionObjectiveCombatantId: type === "extraction" ? stringValue(request.extractionObjectiveCombatantId) : "",
    extractionZoneRegionId: type === "extraction" ? stringValue(request.extractionZoneRegionId) : "",
    holdoutBaseScore: type === "holdout" ? Math.max(Number(request.holdoutBaseScore ?? base.holdoutBaseScore ?? 4), 0) : Number(base.holdoutBaseScore ?? 4),
    reconRegionIds: type === "recon" ? stringList(request.reconRegionIds) : [],
    reconTrueRegionId: type === "recon" ? stringValue(request.reconTrueRegionId) : "",
    startRound, roundLimit, finalRound: startRound + roundLimit - 1,
    rules: { finalZoneControl: request.rules?.finalZoneControl ?? base.rules?.finalZoneControl ?? true, enemyElimination: request.rules?.enemyElimination ?? base.rules?.enemyElimination ?? true, unassailableControl: request.rules?.unassailableControl ?? base.rules?.unassailableControl ?? true }
  };
  if (resetProgress) Object.assign(configured, { scores: { friendly: 0, hostile: 0 }, scoredRounds: [], escortStatus: "active", extractionStatus: "active", reconScannedRegionIds: [], active: true, status: "active", resultReason: "" });
  return normalizeSitrepState(configured);
}

/** Canonical SITREP application orchestration. Unregistered until DM composition Phase 5. */

import { clearSitrepState, readSitrepState, readSitrepStateRecord, updateSitrepState, writeSitrepState } from "../state/sitrep-state-service.js";
import { resolveGauntletEncounterUpdate } from "../gauntlet/gauntlet-resolution.js";
import { resolveControlEncounterUpdate } from "../control/control-resolution.js";
import { resolveHoldoutEncounterUpdate } from "../holdout/holdout-resolution.js";
import { resolveEscortEncounterUpdate } from "../escort/escort-resolution.js";
import { resolveExtractionEncounterUpdate, resolveExtractionObjective } from "../extraction/extraction-resolution.js";
import { recordReconScan, resolveReconEncounterUpdate } from "../recon/recon-resolution.js";
import { buildConfiguredSitrepState, validateSitrepSetup } from "./sitrep-setup.js";

const runtime = { spatialOperations: null, publishOutputIntent: async () => {}, canManageSitreps: () => Boolean(globalThis.game?.user?.isGM) };

export function configureSitrepOrchestrationRuntime({ spatialOperations, publishOutputIntent, canManageSitreps } = {}) {
  if (spatialOperations !== undefined) runtime.spatialOperations = spatialOperations;
  if (publishOutputIntent !== undefined) { if (typeof publishOutputIntent !== "function") throw new TypeError("SITREP output publisher must be a function."); runtime.publishOutputIntent = publishOutputIntent; }
  if (canManageSitreps !== undefined) { if (typeof canManageSitreps !== "function") throw new TypeError("SITREP authorization binding must be a function."); runtime.canManageSitreps = canManageSitreps; }
  return getSitrepOrchestrationDiagnostics();
}

function assertManagePermission() { if (!runtime.canManageSitreps()) throw new Error("Only an authorized GM may manage SITREPs."); }
function requireSpatialOperations() { if (!runtime.spatialOperations) throw new Error("SITREP spatial operations have not been configured."); return runtime.spatialOperations; }
async function publishResultIntents(result) { if (!result) return result; const intents = Array.isArray(result.outputIntents) ? result.outputIntents : result.outputIntent ? [result.outputIntent] : []; for (const intent of intents) await runtime.publishOutputIntent(intent); return result; }

export function getSitrepOperationalState(combat = null) { return readSitrepStateRecord(combat); }
export function getSitrepOrchestrationDiagnostics() { return Object.freeze({ spatialConfigured: Boolean(runtime.spatialOperations), outputPublisherConfigured: typeof runtime.publishOutputIntent === "function", authorizationConfigured: typeof runtime.canManageSitreps === "function" }); }

export async function configureSitrep(request, combat = null) { assertManagePermission(); const existing = readSitrepState(combat); return writeSitrepState(buildConfiguredSitrepState(request, combat, existing, { resetProgress: false }), combat); }
export async function startSitrep(request, combat = null) { assertManagePermission(); const existing = readSitrepState(combat); const state = await writeSitrepState(buildConfiguredSitrepState(request, combat, existing, { resetProgress: true }), combat); await runtime.publishOutputIntent(Object.freeze({ kind: "sitrep-started", sitrepType: state.type, title: state.title, finalRound: state.finalRound })); return state; }
export async function toggleSitrepPause(combat = null) { assertManagePermission(); const sitrep = readSitrepState(combat); if (!sitrep) throw new Error("Cannot pause or resume because no SITREP is configured."); return updateSitrepState({ status: sitrep.status === "paused" ? "active" : "paused" }, combat); }
export async function endSitrep(combat = null) { assertManagePermission(); await clearSitrepState(combat); await runtime.publishOutputIntent(Object.freeze({ kind: "sitrep-ended" })); return null; }
export async function setSitrepResult(status, reason, combat = null) { assertManagePermission(); const normalizedStatus = String(status ?? "").trim().toLowerCase(); if (!["victory", "defeat", "draw"].includes(normalizedStatus)) throw new Error(`Unsupported SITREP result status: ${normalizedStatus}.`); const resultReason = String(reason ?? "").trim(); const state = await updateSitrepState({ status: normalizedStatus, resultReason }, combat); const outputIntent = Object.freeze({ kind: "sitrep-result", sitrepType: state.type, status: normalizedStatus, reason: resultReason }); await runtime.publishOutputIntent(outputIntent); return Object.freeze({ changed: true, state, outputIntent }); }

const encounterResolvers = Object.freeze({ gauntlet: resolveGauntletEncounterUpdate, control: resolveControlEncounterUpdate, holdout: resolveHoldoutEncounterUpdate, escort: resolveEscortEncounterUpdate, extraction: resolveExtractionEncounterUpdate, recon: resolveReconEncounterUpdate });

export async function evaluateSitrepCombatChange(combat, changes = {}) { const sitrep = readSitrepState(combat); if (!sitrep?.active || sitrep.status !== "active") return Object.freeze({ changed: false, state: sitrep, outputIntent: null }); const resolver = encounterResolvers[sitrep.type]; if (!resolver) return Object.freeze({ changed: false, state: sitrep, outputIntent: null }); return publishResultIntents(await resolver(combat, changes, requireSpatialOperations())); }
export async function scanReconRegion(combat, regionId) { assertManagePermission(); return publishResultIntents(await recordReconScan(combat, regionId, requireSpatialOperations())); }
export async function resolveExtractionOutcome(combat, outcome) { assertManagePermission(); return publishResultIntents(await resolveExtractionObjective(combat, outcome, requireSpatialOperations())); }
export { validateSitrepSetup };

/** Canonical Frame Conn SITREP feature package. Phase 4 is real but deliberately unregistered; Phase 5 owns registry/runtime composition. */

import { defineFrameConnFeature } from "../../feature-contract.js";
import { configureSitrepOrchestrationRuntime, configureSitrep, endSitrep, evaluateSitrepCombatChange, getSitrepOperationalState, getSitrepOrchestrationDiagnostics, resolveExtractionOutcome, scanReconRegion, setSitrepResult, startSitrep, toggleSitrepPause, validateSitrepSetup } from "./orchestration/sitrep-orchestrator.js";

export const frameConnSitrepsFeature = defineFrameConnFeature({
  id: "sitreps", domain: "dm-sitreps",
  provides: ["dm.sitreps", "dm.sitreps.state", "dm.sitreps.commands", "dm.sitreps.orchestration"],
  dependsOn: [], optionalDependsOn: ["targeting-spatial"], state: {},
  commands: { configureRuntime: configureSitrepOrchestrationRuntime, configure: configureSitrep, start: startSitrep, togglePause: toggleSitrepPause, end: endSitrep, setResult: setSitrepResult, evaluateCombatChange: evaluateSitrepCombatChange, scanReconRegion, resolveExtractionOutcome },
  queries: { operationalState: getSitrepOperationalState, validateSetup: validateSitrepSetup, diagnostics: getSitrepOrchestrationDiagnostics },
  hooks: {}, lifecycle: {},
  api: { configureRuntime: configureSitrepOrchestrationRuntime, configure: configureSitrep, start: startSitrep, togglePause: toggleSitrepPause, end: endSitrep, setResult: setSitrepResult, evaluateCombatChange: evaluateSitrepCombatChange, scanReconRegion, resolveExtractionOutcome, operationalState: getSitrepOperationalState, validateSetup: validateSitrepSetup, diagnostics: getSitrepOrchestrationDiagnostics },
  metadata: { audience: "gm", phase: "sitrep-assimilation-phase-4", runtimeRegistration: "intentionally-deferred-to-phase-5" }
});

export const FRAME_CONN_SITREP_FEATURES = Object.freeze([frameConnSitrepsFeature]);
